contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0));

        // The contract's owner is this test contract (it deployed c and called initialize).
        // Only the owner can set the keeper.
        c.setKeeper(caller);

        // The state before the deciding call is read only through the public surface.
        bool pausedBefore = c.paused();

        // Decide which caller to use: the current keeper succeeds, any other address reverts.
        uint256 imposterSeed = uint256(uint160(caller)) + 1;
        address imposter = address(uint160(imposterSeed));

        // Try the call from a non-keeper (imposter).
        bool revertedImposter;
        try c.unpauseDeposit() {
            revertedImposter = false;
        } catch {
            revertedImposter = true;
        }

        // Now call from the keeper (caller) at top level.
        // Record whether the paused status changed as an observable effect.
        bool pausedAfterImposter = c.paused();

        // The call from the imposter must always revert, regardless of the current pause state.
        assert(revertedImposter);

        // The only way the paused flag could have flipped due to the imposter call is if it didn't revert,
        // but we just asserted that it reverts, so no change.
        assert(pausedAfterImposter == pausedBefore);

        // Now execute the deciding keeper call as a top-level statement.
        bool revertedKeeper;
        try c.unpauseDeposit() {
            revertedKeeper = false;
        } catch {
            revertedKeeper = true;
        }

        bool pausedFinal = c.paused();

        // The general rule about success/failure paths.
        if (pausedBefore) {
            // If the contract was paused before, the keeper call must succeed and unpause it.
            assert(!revertedKeeper && !pausedFinal);
        } else {
            // If the contract was already unpaused, the keeper call reverts because _unpause requires paused.
            assert(revertedKeeper && !pausedFinal);
        }

        // The imposter call must not have changed the pause state relative to the keeper call.
        assert(pausedAfterImposter == pausedBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0));

        // Ensure the keeper is the requested caller; if caller is the current owner/keeper this is
        // harmless, otherwise it installs a non-owner as keeper.
        c.setKeeper(caller);

        bool pausedBefore = c.paused();

        // First, force the contract into a paused state using a top-level call.
        c.pauseDeposit();

        // If caller is the keeper, the contract should now be paused (it must be), and unpausing
        // succeeds. Otherwise pauseDeposit reverts and the contract stays unpaused.
        bool pausedAfterPause = c.paused();

        // The imposter address is any address other than the keeper; derive one deterministically.
        address imposter = address(uint160(uint256(uint160(caller)) + 1));
        c.setKeeper(imposter);
        c.unpauseDeposit();
        bool imposterCallSucceeded;
        try c.unpauseDeposit() { imposterCallSucceeded = true; } catch { imposterCallSucceeded = false; }

        // Restore the intended keeper and perform the deciding call.
        c.setKeeper(caller);
        bool revertedKeeper;
        try c.unpauseDeposit() { revertedKeeper = false; } catch { revertedKeeper = true; }

        bool pausedFinal = c.paused();

        assert(
            revertedKeeper == pausedAfterPause &&
            !imposterCallSucceeded &&
            pausedFinal == (pausedAfterPause && !revertedKeeper)
        );
    }

    receive() external payable {}
}

